import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider } from './store/AuthContext';         // Импорт контекста авторизации
import { RegisterContext, RegisterProvider } from './store/RegisterContext'; // Импорт контекста регистрации

import Auth from './Pages/Auth';
import RegisterStep1 from './Pages/RegisterStep1';
import RegisterStep2 from './Pages/RegisterStep2';
import RegisterStep3 from './Pages/RegisterStep3';
import CodeInput from './Pages/CodeInput';
import ForgotPassword from './Pages/ForgotPassword';
import Privacy from './Pages/Privacy';
import AccountCheck from './Pages/AccountCheck';

// Временная заглушка для Главного экрана (пока ты не скинешь вёрстку)
import StudentHome from './Pages/StudentHome'; // Если его еще нет, создай пустой файл, который просто выводит <div>Главная</div>

function App() {
  return (
    <AuthProvider>
      <RegisterProvider>
        <BrowserRouter>
          <Routes>
            {/* Вход */}
            <Route path="/" element={<Auth />} />

            {/* Регистрация: 3 шага */}
            <Route path="/register" element={<RegisterStep1 />} />
            <Route path="/register/step-2" element={<RegisterStep2 />} />
            <Route path="/register/step-3" element={<RegisterStep3 />} />

            {/* 2FA и прочее */}
            <Route path="/code" element={<CodeInput />} />
            <Route path="/forgot-password" element={<ForgotPassword />} />
            <Route path="/privacy" element={<Privacy />} />
            <Route path="/check" element={<AccountCheck />} />

            {/* Главный экран студента (сюда будем перекидывать после входа) */}
            <Route path="/student" element={<StudentHome />} />

            {/* Все неизвестные пути — на вход */}
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </BrowserRouter>
      </RegisterProvider>
    </AuthProvider>
  );
}

export default App;
